languages = [
    "azerbaijani", "arabic", "catalan", "chinese", "croatian", "czech", "danish", 
    "dutch", "english", "estonian", "farsi", "french", "german", "hebrew", 
    "hungarian", "italian", "macedonian", "norwegian", "portuguese", 
    "portuguese-br", "russian", "spanish", "swedish", "turkish", "ukrainian"
]

for lang in languages:
    data = translations.get(lang.lower(), translations['english'])
    file_path = os.path.join(lang_dir, f"{lang.lower()}.php")
    
    content = "<?php\n\n"
    for key, val in data.items():
        safe_val = val.replace("'", "\\'")
        content += f"$_ADDONLANG['{key}'] = '{safe_val}';\n"
        
    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(content)

print(f"Translated {len(languages)} files successfully!")
